<?php ($editing=$blog->exists); ?>
<?php $__env->startSection('title',$editing?'Edit Blog':'Add Blog'); ?>
<?php $__env->startSection('content'); ?>
<div class="content-heading mb-4"><h1><?php echo e($editing ? 'Edit Blog' : 'Add New Blog'); ?></h1><p>Write the article once; only published posts appear on the live storefront API.</p></div><form method="POST" action="<?php echo e($editing ? route('admin.blogs.update',$blog) : route('admin.blogs.store')); ?>"><?php echo csrf_field(); ?> <?php if($editing): ?> <?php echo method_field('PUT'); ?> <?php endif; ?><div class="row g-4"><div class="col-xl-8"><div class="panel"><div class="row g-3"><div class="col-12"><label class="form-label">Title <span class="text-danger">*</span></label><input name="title" value="<?php echo e(old('title',$blog->title)); ?>" class="form-control" required></div><div class="col-md-6"><label class="form-label">Category</label><select name="category_id" class="form-select"><option value="">Uncategorized</option><?php $__currentLoopData = $categories; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $category): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($category->id); ?>" <?php if(old('category_id',$blog->category_id)==$category->id): echo 'selected'; endif; ?>><?php echo e($category->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><div class="col-md-6"><label class="form-label">Tags</label><select name="tags[]" class="form-select js-tag-select" multiple><?php $__currentLoopData = old('tags',$blog->tags ?? []); $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $tag): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($tag); ?>" selected><?php echo e($tag); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><div class="form-text">Type a tag and press Enter. You can add multiple tags.</div></div><div class="col-12"><label class="form-label">Description <span class="text-danger">*</span></label><textarea name="description" rows="14" class="form-control" required><?php echo e(old('description',$blog->description)); ?></textarea></div><div class="col-md-6"><label class="form-label">Meta title</label><input name="meta_title" value="<?php echo e(old('meta_title',$blog->meta_title)); ?>" class="form-control"></div><div class="col-md-6"><label class="form-label">Status</label><select name="status" class="form-select"><option value="draft" <?php if(old('status',$blog->status)==='draft'): echo 'selected'; endif; ?>>Draft</option><option value="published" <?php if(old('status',$blog->status)==='published'): echo 'selected'; endif; ?>>Published</option></select></div><div class="col-12"><label class="form-label">Meta description</label><textarea name="meta_description" rows="3" class="form-control"><?php echo e(old('meta_description',$blog->meta_description)); ?></textarea></div></div></div></div><div class="col-xl-4"><div class="panel"><div class="panel-heading mb-2">Blog thumbnail</div><p class="small text-muted">Recommended ratio: 4:3 or 1280 × 960 px.</p><div class="media-preview mb-3" data-media-preview="blog-thumbnail"><?php if($blog->thumbnail): ?><img src="<?php echo e($blog->thumbnail->url); ?>" alt="<?php echo e($blog->title); ?>"><?php else: ?><i class="bi bi-image fs-1"></i><?php endif; ?></div><input type="hidden" id="blog-thumbnail" name="thumbnail_media_id" value="<?php echo e(old('thumbnail_media_id',$blog->thumbnail_media_id)); ?>"><button type="button" class="btn btn-outline-primary w-100" data-media-picker-target="blog-thumbnail"><i class="bi bi-images me-1"></i>Choose from Media Library</button></div></div></div><div class="mt-4"><a href="<?php echo e(route('admin.blogs.index')); ?>" class="btn btn-light">Cancel</a><button class="btn text-white ms-2" style="background:var(--brand)"><?php echo e($editing ? 'Update blog' : 'Save blog'); ?></button></div></form>
<?php $__env->stopSection(); ?>

